package main

import (
	"cmp"
	"fmt"
	"maps"
	"slices"
	"sort"
)

type Task struct {
	Name  string
	Score int
}

func main() {
	nums := []int{3, 1, 2, 2}
	sort.Ints(nums)
	fmt.Println("排序后:", nums)

	nums = slices.Compact(nums)
	fmt.Println("去重后:", nums)

	words := []string{"pear", "apple"}
	slices.Sort(words)
	fmt.Println("字符串排序:", words)

	tasks := []Task{{Name: "甲", Score: 90}, {Name: "乙", Score: 80}}
	slices.SortFunc(tasks, func(a, b Task) int {
		return cmp.Compare(a.Score, b.Score)
	})
	fmt.Println("按分数排序:", tasks)

	fmt.Println("最高分:", slices.Max(nums), "最低分:", slices.Min(nums))

	idx, found := slices.BinarySearch(nums, 2)
	fmt.Println("二分查找 2:", idx, found)

	scores := map[string]int{"bob": 80, "alice": 90}
	keys := slices.Sorted(maps.Keys(scores))
	fmt.Println("键（已排序）:", keys)

	backup := maps.Clone(scores)
	delete(backup, "bob")
	fmt.Println("副本:", len(backup), "原 map:", len(scores))

	label := cmp.Or("", "默认名称")
	fmt.Println("名称:", label)
}
